use std::collections::HashSet;

fn has_common_element(a: &Vec<i32>, b: &Vec<i32>) -> bool {
    // Put the elements of the smaller vector into a HashSet to save space/time
    if a.len() < b.len() {
        let set: HashSet<i32> = a.iter().copied().collect();
        b.iter().any(|&x| set.contains(&x))
    } else {
        let set: HashSet<i32> = b.iter().copied().collect();
        a.iter().any(|&x| set.contains(&x))
    }
}

